using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
namespace ClearSpace {
public static class V3Tests {
 public static int Run(string output){Directory.CreateDirectory(output);var tests=new List<string>();Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("FAILED: "+label);tests.Add("PASS: "+label);};Func<Action,bool> rejected=action=>{try{action();return false;}catch{return true;}};string fixture=Path.Combine(Path.GetFullPath(output),"v3-fixture-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(fixture);
 try{
  check(ApplicationDiscovery.ExecutableFromCommand("\"C:\\Program Files\\Example\\app.exe\" --arg")=="C:\\Program Files\\Example\\app.exe","Executable parser preserves quoted custom installation paths");check(ApplicationDiscovery.ExecutableFromCommand("relative.exe")==null&&ApplicationDiscovery.ExecutableFromCommand(@"\\server\app.exe")==null,"Application discovery does not follow relative or network executables");var app=new ApplicationIdentity{Name="Chrome",Publisher="Google",Product="Chromium",Company="Google",Executable="C:\\Apps\\chrome.exe"};check(ApplicationDiscovery.Matches(app,new[]{"Chrome"},new[]{"chrome.exe"},new[]{"Google"})&&!ApplicationDiscovery.Matches(app,new[]{"Chrome"},new[]{"chrome.exe"},new[]{"Microsoft"}),"Fingerprint matching checks publisher as well as executable evidence");
  var browserDefinition=new ApplicationRule{MatchNames=new[]{"Chrome"},ExecutableNames=new[]{"chrome.exe"},ProductNames=new[]{"Google Chrome"}};check(!RuleStore.MatchesDefinition(browserDefinition,app),"Product fingerprints distinguish Chromium from Chrome despite the same executable name");app.Product="Google Chrome";check(RuleStore.MatchesDefinition(browserDefinition,app),"Confirmed product name matches its browser definition");browserDefinition.RequireSignature=true;app.Signature="未验证签名";check(!RuleStore.MatchesDefinition(browserDefinition,app),"Rules requiring signatures retain unverified executables");
  RuleStore.Validate(RuleStore.Defaults());check(new RuleStore().Current().Trust=="发布者签名已验证","Bundled application rules have a verified publisher signature");check(rejected(()=>PathPolicy.ValidateTemplate(@"C:\Users\owner\Documents\Cache"))&&rejected(()=>PathPolicy.ValidateTemplate(@"%LOCALAPPDATA%\Example\..\Cache"))&&rejected(()=>PathPolicy.ValidateTemplate(@"%LOCALAPPDATA%\Example\User")),"Rule paths reject absolute personal paths, traversal and non-cache directories");check(rejected(()=>PathPolicy.ValidateTemplate(@"%USERPROFILE%\Downloads\Cache")),"External rules cannot expand arbitrary environment variables");PathPolicy.ValidateTemplate(@"%LOCALAPPDATA%\Example\*\GPUCache");check(true,"Cache templates allow bounded profile wildcards");
  var invalid=RuleStore.Defaults();invalid.Rules[0].Group="注册表";check(rejected(()=>RuleStore.Validate(invalid)),"Application rule imports cannot define registry or system cleanup");invalid=RuleStore.Defaults();invalid.Rules[0].Method="execute";check(rejected(()=>RuleStore.Validate(invalid)),"Rule imports reject executable cleanup actions");
  invalid=RuleStore.Defaults();invalid.Rules[0].MatchNames=new[]{""};check(rejected(()=>RuleStore.Validate(invalid)),"Empty fingerprint terms cannot match every discovered application");
  var parameters=new CspParameters{ProviderType=24,Flags=CspProviderFlags.CreateEphemeralKey};using(var rsa=new RSACryptoServiceProvider(2048,parameters)){rsa.PersistKeyInCsp=false;var store=new RuleStore(Path.Combine(fixture,"rules"),rsa.ToXmlString(false));Func<string,string> signed=version=>{var pack=RuleStore.Defaults();pack.Version=version;byte[] bytes=Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(pack));return new JavaScriptSerializer().Serialize(new SignedRuleEnvelope{Payload=Convert.ToBase64String(bytes),Signature=Convert.ToBase64String(rsa.SignData(bytes,CryptoConfig.MapNameToOID("SHA256")))});};store.Import(signed("3.0.0"),true);store.Import(signed("3.0.1"),false);check(store.Current().Pack.Version=="3.0.1","New signed rule version is atomically activated");string before=File.ReadAllText(Path.Combine(store.DirectoryPath,"active.json"));var envelope=new JavaScriptSerializer().Deserialize<SignedRuleEnvelope>(signed("3.0.2"));envelope.Payload=Convert.ToBase64String(Encoding.UTF8.GetBytes("{}"));check(rejected(()=>store.Import(new JavaScriptSerializer().Serialize(envelope),false))&&File.ReadAllText(Path.Combine(store.DirectoryPath,"active.json"))==before,"Tampered cloud rules are rejected without changing active rules");check(rejected(()=>store.Import(new JavaScriptSerializer().Serialize(RuleStore.Defaults()),false)),"Cloud updates reject unsigned rule packs");check(rejected(()=>store.Import(signed("2.9.0"),false))&&store.Current().Pack.Version=="3.0.1","Cloud updates cannot silently downgrade the rule version");check(store.Rollback().Pack.Version=="3.0.0","Explicit rollback restores the previous validated rule pack");check(rejected(()=>store.Update("http://example.com/rules.json",CancellationToken.None)),"Cloud transport rejects plain HTTP before making a request");store.Import(new JavaScriptSerializer().Serialize(RuleStore.Defaults()),true);check(store.Current().Trust=="本地导入 · 未签名","Manual unsigned import remains explicitly marked untrusted");}
  string cache=Path.Combine(fixture,"Example","Cache");Directory.CreateDirectory(cache);Directory.CreateDirectory(Path.Combine(cache,"User"));Directory.CreateDirectory(Path.Combine(cache,"IndexedDB"));Action<string,string> write=(name,value)=>{string path=Path.Combine(cache,name);File.WriteAllText(path,value);File.SetLastWriteTimeUtc(path,DateTime.UtcNow.AddDays(-60));};write("old.log","diagnostic fixture");write("recent.tmp","recent");File.SetLastWriteTimeUtc(Path.Combine(cache,"recent.tmp"),DateTime.UtcNow);write("document.tmp","%PDF personal document");write("database.tmp","SQLite format 3\0personal data");write("User\\notes.log","personal");write("IndexedDB\\data.log","database");
  var heuristic=new Rule("heuristic-fixture","unknown","软件缓存","desc","impact",new[]{cache},30,false){Heuristic=true,Extensions=new[]{".tmp",".log",".cache",".dmp"},ExcludedNames=PathPolicy.SensitiveNames};var engine=new Engine(new List<Rule>{heuristic}){FileBackupDirectory=Path.Combine(fixture,"backups")};var finding=engine.ScanRule(heuristic,CancellationToken.None);check(finding.Candidates.Count==1&&finding.Candidates[0].Path==Path.Combine(cache,"old.log"),"Heuristics exclude recent files, document/database headers and sensitive directories");var result=engine.Clean(new[]{finding},true,CancellationToken.None,null);check(result.Deleted==0&&File.Exists(Path.Combine(cache,"old.log")),"Heuristic candidates never participate in one-click cleanup");result=engine.Clean(new[]{finding},false,CancellationToken.None,null);check(result.Deleted==1&&result.BackupFiles==1&&File.Exists(result.FileBackupManifest),"Heuristic advanced cleanup forces a durable recovery backup");check(result.EstimatedFreedBytes==0,"Same-drive backup does not falsely report net released space");var entries=FileRecovery.Read(result.FileBackupManifest);check(entries.Count==1&&entries[0].Hash.Length==64,"Recovery index is authenticated for this account and contains a content hash");check(FileRecovery.Restore(result.FileBackupManifest,false)==1&&File.ReadAllText(Path.Combine(cache,"old.log"))=="diagnostic fixture","Recovery restores exact original content");File.WriteAllText(Path.Combine(cache,"old.log"),"new original");check(FileRecovery.Restore(result.FileBackupManifest,false)==0&&File.ReadAllText(Path.Combine(cache,"old.log"))=="new original","Recovery does not overwrite an existing file");
  string stored=Path.Combine(Path.GetDirectoryName(result.FileBackupManifest),entries[0].Stored);File.Delete(Path.Combine(cache,"old.log"));File.AppendAllText(stored,"tamper");check(rejected(()=>FileRecovery.Restore(result.FileBackupManifest,false))&&!File.Exists(Path.Combine(cache,"old.log")),"Corrupted backup content blocks restoration");check(rejected(()=>FileRecovery.Read(CreateInvalidManifest(fixture))),"Unauthenticated recovery indexes are rejected");
  write("old.log","backup failure fixture");engine.FileBackupDirectory=Path.Combine(fixture,"not-a-directory");File.WriteAllText(engine.FileBackupDirectory,"blocked");finding=engine.ScanRule(heuristic,CancellationToken.None);check(rejected(()=>engine.Clean(new[]{finding},false,CancellationToken.None,null))&&File.Exists(Path.Combine(cache,"old.log")),"Backup destination failure prevents original file deletion");
  var exclude=new Rule("exclude-test","exclude","软件缓存","","",new[]{cache},1,false){ExcludedRoots=new[]{Path.Combine(cache,"User")},ExcludedNames=new[]{"IndexedDB"},FileNameRegex="^old\\.log$"};engine=new Engine(new List<Rule>{exclude});finding=engine.ScanRule(exclude,CancellationToken.None);check(finding.Candidates.Count==1&&!exclude.Accept(Path.Combine(cache,"User","notes.log")),"Explicit exclusions and filename regex apply at scan and deletion boundaries");
  string copied=Path.Combine(fixture,"copy","nested");Directory.CreateDirectory(copied);File.WriteAllText(Path.Combine(copied,"portable.exe"),"fixture, never executed");check(ApplicationDiscovery.FilesBounded(Path.Combine(fixture,"copy"),".exe",3,20,CancellationToken.None).Count()==1,"Portable executable discovery uses bounded read-only traversal");
  File.AppendAllText(result.FileBackupManifest,"interrupted-record");check(FileRecovery.Read(result.FileBackupManifest).Count==1,"An interrupted final journal record preserves earlier authenticated recovery entries");
  write("cancel.tmp",new string('x',131072));var cancelRule=new Rule("cancel-backup","cancel","软件缓存","","",new[]{cache},1,false){FileNameRegex="^cancel\\.tmp$"};var cancelFinding=new Engine(new List<Rule>{cancelRule}).ScanRule(cancelRule,CancellationToken.None);var session=new RecoverySession(Path.Combine(fixture,"cancel-backups"));bool cancelObserved=false;using(var cancelled=new CancellationTokenSource())using(var handle=Native.CreateFile(Path.Combine(cache,"cancel.tmp"),0x80000000u,1,IntPtr.Zero,3,0x200000,IntPtr.Zero)){if(handle.IsInvalid)throw new IOException("Cannot open cancellation fixture");cancelled.Cancel();try{session.Save(handle,cancelRule,cancelFinding.Candidates.Single(),cancelled.Token);}catch(OperationCanceledException){cancelObserved=true;}}check(cancelObserved&&File.Exists(Path.Combine(cache,"cancel.tmp"))&&Directory.GetFiles(session.DirectoryPath,"*.bin").Length==0,"Backup cancellation retains the original and removes the incomplete backup file");
  string configuredRecovery=Path.Combine(cache,"configured-recovery"),oldRecovery=Path.Combine(cache,"previous-recovery");Directory.CreateDirectory(configuredRecovery);Directory.CreateDirectory(oldRecovery);write("configured-recovery\\saved.log","saved");write("previous-recovery\\saved.log","saved");write("ordinary.log","ordinary");File.WriteAllText(Path.Combine(oldRecovery,"files.csbackup"),"recovery marker fixture");var guardRule=new Rule("backup-guard","backup guard","软件缓存","","",new[]{cache},1,true){FileNameRegex="^(saved|ordinary)\\.log$"};var guardEngine=new Engine(new List<Rule>{guardRule}){FileBackupDirectory=configuredRecovery};var guardFinding=guardEngine.ScanRule(guardRule,CancellationToken.None);check(guardFinding.Candidates.Count==1&&guardFinding.Candidates[0].Path==Path.Combine(cache,"ordinary.log"),"Scanning excludes configured backup locations and previous backup job directories");
  string lateRecovery=Path.Combine(cache,"late-recovery");Directory.CreateDirectory(lateRecovery);write("late-recovery\\saved.log","preserve");var lateRule=new Rule("late-backup-guard","late guard","软件缓存","","",new[]{lateRecovery},1,true);guardEngine=new Engine(new List<Rule>{lateRule});guardFinding=guardEngine.ScanRule(lateRule,CancellationToken.None);File.WriteAllText(Path.Combine(lateRecovery,"files.csbackup"),"created after scan");var guardResult=guardEngine.Clean(new[]{guardFinding},true,CancellationToken.None,null);check(guardResult.Deleted==0&&File.Exists(Path.Combine(lateRecovery,"saved.log")),"Deletion rechecks backup protection even when a recovery index appears after scanning");
  RulePackTests.Verify(fixture,check);
  File.WriteAllLines(Path.Combine(output,"v3-test-results.txt"),tests.Concat(new[]{"ALL "+tests.Count+" V3 CHECKS PASSED","Only generated workspace fixtures were modified."}));return 0;
 }catch(Exception ex){File.WriteAllLines(Path.Combine(output,"v3-test-results.txt"),tests.Concat(new[]{ex.ToString()}));return 1;}}
 static string CreateInvalidManifest(string directory){string file=Path.Combine(directory,"invalid.csbackup");File.WriteAllText(file,Convert.ToBase64String(Encoding.UTF8.GetBytes("untrusted")));return file;}
}
